 border: none;
 text-align: left;
 outline: none;
 font-size: 16px;
 }
 .content {
 display: none;
 padding-left: 15px;
 font-size: 14px;
 }
 .active + .content {
 display: block;
 }
 </style>
</head>
<body>
 <nav class="sidebar">
 <div class="nav-item">
 <button class="collapsible">Section 1</button>
 <div class="content">
 <a href="#">Link 1.1</a>
 <a href="#">Link 1.2</a>
 <a href="#">Link 1.3</a>
 </div>
 </div>
 <div class="nav-item">
 <button class="collapsible">Section 2</button>
 <div class="content">
 <a href="#">Link 2.1</a>
 <a href="#">Link 2.2</a>
 <a href="#">Link 2.3</a>
 </div>
 </div>
 </nav>
 <script>
 const collapsibles = document.querySelectorAll('.collapsible');
 collapsibles.forEach((collapsible) => {
 collapsible.addEventListener('click', function() {
 this.classList.toggle('active');
 let content = this.nextElementSibling;
 if (content.style.display === "block") {
 content.style.display = "none";
 } else {
 content.style.display = "block";
 }
 });
 });
 </script>
</body>
</html>
```

### Explanation:
- **HTML Structure**: The sidebar contains collapsible sections, each made of a button and a hidden content area.
- **CSS Styling**: Basic styles for the sidebar, buttons, and hidden content. Active sections display their content.
- **JavaScript**: Listens for button clicks to toggle the visibility of content.

