 margin-bottom: 15px;
 }
 .responsive-table th {
 background: #f4f4f4;
 font-weight: bold;
 }
 .responsive-table td {
 border: none;
 border-bottom: 1px solid #eee;
 position: relative;
 padding-left: 50%;
 white-space: nowrap;
 }
 .responsive-table td::before {
 position: absolute;
 top: 0;
 left: 0;
 width: 45%;
 padding-right: 10px;
 white-space: nowrap;
 content: attr(data-label);
 font-weight: bold;
 }
 }
 </style>
</head>
