### Server-Side Validation with Express Validator

To validate this form server-side with Express Validator, you'll first need to set up a Node.js server. Install the Express Validator library using npm:

```bash
npm install express-validator
```

Here's a sample Node.js server setup with validation:

```javascript
const express = require('express');
const { body, validationResult } = require('express-validator');
const app = express();

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.post('/submit-contact', [
 body('name').notEmpty().withMessage('Name is required'),
 body('email').isEmail().withMessage('Enter a valid email'),
 body('message').notEmpty().withMessage('Message cannot be empty')
], (req, res) => {
 const errors = validationResult(req);
 if (!errors.isEmpty()) {
 return res.status(400).json({ errors: errors.array() });
 }

 // Handle the form submission logic here
 res.send('Form submitted successfully');
});

app.listen(3000, () => {
 console.log('Server running on http://localhost:3000');
});
```

This example sets up a basic server that validates the name, email, and message fields to ensure they're filled out correctly and returns errors if they aren't.

