<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Multi-Step Form Wizard</title>
 <style>
 body { font-family: Arial, sans-serif; }
 .form-step { display: none; }
 .form-step.active { display: block; }
 .form-navigation { margin-top: 20px; }
 .form-navigation button { padding: 10px 20px; }
 </style>
</head>
<body>

 <form id="multiStepForm">
 <!-- Step 1: Personal Info -->
 <div class="form-step active" id="step1">
 <h2>Personal Information</h2>
 <label for="name">Name:</label>
 <input type="text" id="name" name="name" required><br>
 <label for="email">Email:</label>
 <input type="email" id="email" name="email" required><br>
 </div>

 <!-- Step 2: Address Details -->
 <div class="form-step" id="step2">
 <h2>Address Details</h2>
 <label for="address">Address:</label>
 <input type="text" id="address" name="address" required><br>
 <label for="city">City:</label>
 <input type="text" id="city" name="city" required><br>
 </div>

 <!-- Step 3: Confirmation -->
 <div class="form-step" id="step3">
 <h2>Confirmation</h2>
 <p>Review your information before submission.</p>
 </div>

 <!-- Navigation -->
 <div class="form-navigation">
 <button type="button" id="prevButton">Previous</button>
 <button type="button" id="nextButton">Next</button>
 <button type="submit" id="submitButton" style="display: none;">Submit</button>
 </div>
 </form>

 <script>
 const steps = document.querySelectorAll('.form-step');
 let currentStep = 0;

 document.getElementById('nextButton').addEventListener('click', () => {
 if (currentStep < steps.length - 1) {
 steps[currentStep].classList.remove('active');
 currentStep++;
 steps[currentStep].classList.add('active');
 }
 toggleButtons();
 });

 document.getElementById('prevButton').addEventListener('click', () => {
 if (currentStep > 0) {
 steps[currentStep].classList.remove('active');
 currentStep--;
 steps[currentStep].classList.add('active');
 }
 toggleButtons();
 });

 function toggleButtons() {
 document.getElementById('prevButton').style.display = currentStep === 0 ? 'none' : 'inline';
 document.getElementById('nextButton').style.display = currentStep === steps.length - 1 ? 'none' : 'inline';
 document.getElementById('submitButton').style.display = currentStep === steps.length - 1 ? 'inline' : 'none';
 }

 toggleButtons();
 </script>

</body>
</html>
```
