Certainly! Lazy loading is an effective way to enhance performance by only loading images when they're about to enter the viewport. Here's a simple example using the Intersection Observer API:

```html
<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Lazy Loading Images Example</title>
 <style>
 .image-container {
 width: 100%;
 height: 300px;
 display: flex;
 justify-content: center;
 align-items: center;
 margin-bottom: 20px;
 }
 .placeholder {
 background-color: #f0f0f0;
 width: 100%;
 height: 100%;
 text-align: center;
 font-size: 1.2em;
 color: #aaa;
 }
 </style>
</head>
<body>
 <section>
 <h1>Lazy Loading Images with Intersection Observer</h1>
 <div class="image-container">
 <img data-src="high-res-image1.jpg" alt="Beautiful Landscape" class="lazy-image placeholder">
 </div>
 <div class="image-container">
 <img data-src="high-res-image2.jpg" alt="City Skyline" class="lazy-image placeholder">
 </div>
 </section>

 <script>
 document.addEventListener("DOMContentLoaded", function() {
 const lazyImages = document.querySelectorAll('.lazy-image');

 const imageObserver = new IntersectionObserver((entries, observer) => {
 entries.forEach(entry => {
 if (entry.isIntersecting) {
 const img = entry.target;
 img.src = img.getAttribute('data-src');
 img.classList.remove('placeholder');
 observer.unobserve(img);
 }
 });
 });

 lazyImages.forEach(image => {
 imageObserver.observe(image);
 });
 });
 </script>
</body>
</html>
```

In this example:
- Each image has a 'lazy-image' class and a 'data-src' attribute containing the actual image URL.
- A placeholder style is applied to give a visual cue until the image loads.
- The Intersection Observer tracks when each image enters the viewport, updating the `src` attribute and removing the placeholder class.

